arguments.command:
curl -s https://api.linear.app/graphql -X POST -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"{ __schema { queryType { fields { name args { name type { name kind } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if f['name'] in ('project','issue','document'):
        print(f['name'], [(a['name'],a['type']) for a in f['args']])"

